    // isRelightNode
    "ComfyTV.PosterStage",
    // isPosterNode
    "ComfyTV.LayerEditorStage",
    // isLayerEditorNode
    "ComfyTV.StoryboardEditorStage",
    // isStoryboardEditorNode
    "ComfyTV.MaterialStage",
    // isMaterialNode
    "ComfyTV.Scene3DStage",
    // isScene3DNode
