  expect(resolveShortcutAction(k("c", { altKey: true })) === "collapse", "Alt+C \u2192 collapse");
  expect(resolveShortcutAction(k("d", { ctrlKey: true })) === "duplicate", "Ctrl+D \u2192 duplicate");
