section("P3 CropEditor: \u4EA4\u4E92\u5F0F\u88C1\u526A\u7EAF\u903B\u8F91\uFF08\u5F52\u4E00\u5316 \u2194 \u50CF\u7D20 / \u547D\u4E2D / \u62D6\u62FD\uFF09");
{
  const { pxToNorm: pxToNorm2, normToPx: normToPx2, hitTestCrop: hitTestCrop2, dragCrop: dragCrop2, dragNewCrop: dragNewCrop2, fullCrop: fullCrop2, fullCropNorm: fullCropNorm2 } = await Promise.resolve().then(() => (init_cropEditor(), cropEditor_exports));
  const px3 = { x: 100, y: 50, width: 200, height: 100 };
  const n2 = pxToNorm2(px3, 400, 200);
  expect(
    Math.abs(n2.x - 0.25) < 1e-9 && Math.abs(n2.y - 0.25) < 1e-9 && Math.abs(n2.w - 0.5) < 1e-9 && Math.abs(n2.h - 0.5) < 1e-9,
    "pxToNorm \u6B63\u786E\u5F52\u4E00\u5316 (" + JSON.stringify(n2) + ")"
  );
  const back = normToPx2(n2, 400, 200);
  expect(back.x === 100 && back.y === 50 && back.width === 200 && back.height === 100, "normToPx \u8FD8\u539F\u50CF\u7D20 (" + JSON.stringify(back) + ")");
  const clamped = pxToNorm2({ x: 380, y: 180, width: 500, height: 500 }, 400, 200);
  expect(
    clamped.x < 1 && clamped.y < 1 && clamped.w <= 1 - clamped.x + 1e-9 && clamped.h <= 1 - clamped.y + 1e-9,
    "pxToNorm clamp \u5230\u8FB9\u754C (" + JSON.stringify(clamped) + ")"
  );
  expect(fullCrop2(400, 200).width === 400 && fullCrop2(400, 200).height === 200, "fullCrop \u5168\u56FE");
  expect(fullCropNorm2().w === 1 && fullCropNorm2().h === 1, "fullCropNorm \u5168\u56FE\u5F52\u4E00\u5316");
  const box = { x: 0.25, y: 0.25, w: 0.5, h: 0.5 };
  expect(hitTestCrop2(box, 0.25, 0.25, 0.05) === "tl", "hit \u5DE6\u4E0A\u89D2");
  expect(hitTestCrop2(box, 0.75, 0.75, 0.05) === "br", "hit \u53F3\u4E0B\u89D2");
  expect(hitTestCrop2(box, 0.5, 0.5, 0.05) === "move", "hit \u5185\u90E8 \u2192 move");
  expect(hitTestCrop2(box, 0.1, 0.1, 0.05) === null, "\u5916\u90E8 \u2192 null");
  const moved = dragCrop2("move", { x: 0.25, y: 0.25, w: 0.5, h: 0.5 }, 0.5, 0.5, 0.6, 0.7);
  expect(
    Math.abs(moved.x - 0.35) < 1e-9 && Math.abs(moved.y - 0.45) < 1e-9 && Math.abs(moved.w - 0.5) < 1e-9 && Math.abs(moved.h - 0.5) < 1e-9,
    "move \u5E73\u79FB (+0.1,+0.2) (" + JSON.stringify(moved) + ")"
  );
  const resized = dragCrop2("br", { x: 0.25, y: 0.25, w: 0.5, h: 0.5 }, 0.75, 0.75, 0.85, 0.8);
  expect(
    Math.abs(resized.w - 0.6) < 1e-9 && Math.abs(resized.h - 0.55) < 1e-9 && Math.abs(resized.x - 0.25) < 1e-9,
    "br \u7F29\u653E (w+0.1,h+0.05)\uFF0C\u951A\u70B9\u4E0D\u53D8 (" + JSON.stringify(resized) + ")"
  );
  const nc = dragNewCrop2(0.2, 0.2, 0.6, 0.5);
  expect(
    Math.abs(nc.x - 0.2) < 1e-9 && Math.abs(nc.y - 0.2) < 1e-9 && Math.abs(nc.w - 0.4) < 1e-9 && Math.abs(nc.h - 0.3) < 1e-9,
    "dragNewCrop \u62D6\u9009 (" + JSON.stringify(nc) + ")"
  );
}
section("P3 MaskPainter: \u4EA4\u4E92\u5F0F\u64E6\u9664 mask \u7EAF\u903B\u8F91\uFF08\u5BF9\u9F50 ComfyTV commitMask\uFF09");
