section("P3 Scene3D: environment/output patch \u7EAF\u903B\u8F91");
{
  const { patchEnvironment: patchEnvironment2, patchOutput: patchOutput2, createEmptyScene: createEmptyScene3, parseSceneState: parseSceneState2, sceneStateToJson: sceneStateToJson2 } = await Promise.resolve().then(() => (init_scene3dEditor(), scene3dEditor_exports));
  let s = createEmptyScene3();
  s = patchEnvironment2(s, { showGrid: false, background: "#123456" });
  expect(s.environment.showGrid === false && s.environment.background === "#123456", "patchEnvironment \u6539 showGrid/background");
  expect(s.primitives.length === 0 && s.output.fps === 24, "patchEnvironment \u4E0D\u52A8\u5176\u4ED6\u5B57\u6BB5");
  s = patchOutput2(s, { fps: 30, frameCount: 100, cameraId: "cam_9" });
  expect(s.output.fps === 30 && s.output.frameCount === 100 && s.output.cameraId === "cam_9", "patchOutput \u6539 fps/frameCount/cameraId");
  expect(s.environment.showGrid === false, "patchOutput \u4E0D\u52A8 environment");
  const round3 = parseSceneState2(sceneStateToJson2(s));
  expect(round3.environment.showGrid === false && round3.environment.background === "#123456" && round3.output.fps === 30 && round3.output.cameraId === "cam_9", "environment/output \u5E8F\u5217\u5316\u5F80\u8FD4");
}
section("P3 Scene3D: timeline \u7EAF\u903B\u8F91\uFF08\u5BF9\u9F50 ComfyTV TimelineController + characterTime + timelineMath\uFF09");
{
  const {
    SceneTimelineController: SceneTimelineController2,
    characterElapsedTime: characterElapsedTime2,
    clipLocalTime: clipLocalTime2,
    actionSampleTime: actionSampleTime2,
    sceneFallbackDuration: sceneFallbackDuration2,
    computeTotalFrames: computeTotalFrames2,
    zoomFromExp: zoomFromExp2,
    resolveContainerHeight: resolveContainerHeight2
  } = await Promise.resolve().then(() => (init_scene3dTimeline(), scene3dTimeline_exports));
  const events = [];
  const ctrl = new SceneTimelineController2(24, {
    onTimeUpdate: (frame, time) => events.push(["time", frame, time]),
    onStateChange: (playing, loop) => events.push(["state", playing, loop])
  });
  expect(ctrl.totalFrames === 1 && ctrl.hasContent() === false, "\u521D\u59CB totalFrames=1\uFF08Math.max(1,...)\uFF09/hasContent=false");
  ctrl.setTimelineDuration(2);
  expect(ctrl.totalFrames === 48 && ctrl.hasContent() === true, "setTimelineDuration(2s) \u2192 48 \u5E27");
  ctrl.play();
  expect(ctrl.isPlayingNow() === true, "play \u540E playing");
  ctrl.update(0.5);
  expect(ctrl.getCurrentFrame() === 12, "update(0.5s) \u2192 frame 12");
  ctrl.pause();
  expect(ctrl.isPlayingNow() === false, "pause \u540E\u505C\u6B62");
  ctrl.seekToFrame(24);
  expect(ctrl.getCurrentFrame() === 24 && Math.abs(ctrl.getCurrentTime() - 1) < 1e-9, "seekToFrame(24) \u2192 time 1.0");
  ctrl.seekToTime(1.5);
  expect(ctrl.getCurrentFrame() === 36, "seekToTime(1.5) \u2192 frame 36");
  ctrl.setTimelineDuration(1);
  ctrl.play();
  ctrl.update(1.5);
  expect(ctrl.isPlayingNow() === true && ctrl.getCurrentTime() < 1, "loop \u64AD\u653E\u8D85\u65F6\u957F\u56DE\u7ED5");
  ctrl.pause();
  ctrl.seekToTime(0);
  ctrl.setLoopPlayback(false);
  ctrl.play();
  ctrl.update(1.5);
  expect(ctrl.isPlayingNow() === false && Math.abs(ctrl.getCurrentTime() - 1) < 1e-9, "\u975E loop \u5230\u7ED3\u5C3E\u505C\u6B62");
  ctrl.reset();
  expect(ctrl.totalFrames === 1 && ctrl.isPlayingNow() === false, "reset \u6E05\u7A7A");
  expect(characterElapsedTime2(2, { startOffset: 1, speed: 2, loop: true }) === 5, "characterElapsedTime = startOffset + t*speed");
  expect(clipLocalTime2(5, 4, true) === 1, "clipLocalTime loop \u56DE\u7ED5 (5 % 4 = 1)");
  expect(clipLocalTime2(5, 4, false) === 4, "clipLocalTime \u975E loop clamp \u5230 duration");
  expect(actionSampleTime2(5, 4, false) === 4 - 1e-4, "actionSampleTime \u975E loop \u5230\u7ED3\u5C3E\u53D6 duration-1e-4");
  const chars = [{ model: "m1", animation: { clip: "walk", startOffset: 0, speed: 2, loop: true } }];
  const clips = /* @__PURE__ */ new Map([["m1:walk", 4]]);
  expect(sceneFallbackDuration2(chars, clips) === 2, "sceneFallbackDuration = clipDuration / speed = 4/2 = 2");
  expect(sceneFallbackDuration2([], /* @__PURE__ */ new Map()) === 1, "\u65E0\u89D2\u8272\u65F6 fallback = 1");
  expect(computeTotalFrames2({ cameras: [{ sourceFrames: 100, speed: 2 }], characters: [] }) === 50, "computeTotalFrames camera 100/2=50");
  expect(computeTotalFrames2({ cameras: [], characters: [{ offsetFrames: 10, displayFrames: 30 }] }) === 40, "computeTotalFrames character 10+30=40");
  expect(computeTotalFrames2(null) === 0, "computeTotalFrames null \u2192 0");
  expect(zoomFromExp2(2) === 4 && zoomFromExp2(0) === 1, "zoomFromExp = 2^exp");
  expect(resolveContainerHeight2(0) === 80 && resolveContainerHeight2(120) === 120, "resolveContainerHeight 0\u219280 \u515C\u5E95");
}
section("P3 Scene3D: local execution emits the capture");
{
  const store = {
    put: () => {
    },
    byNode: (id) => id === "sc" ? [{ nodeId: "sc", port: "output", key: "sc:output:0", media: { kind: "image", ref: "http://x/scene.png" }, index: 0 }] : []
  };
  const r = await runScene3DNode({ nodeId: "sc", values: {}, store });
  expect(r.status === "success" && r.entries.length === 1 && r.entries[0].media.ref === "http://x/scene.png", "scene emits its capture snapshot");
  const rEmpty = await runScene3DNode({ nodeId: "empty", values: {}, store });
  expect(rEmpty.status === "error", "scene without a capture errors");
}
section("REAL-ENGINE (optional): \u5185\u7F6E\u6A21\u677F\u5728\u7EAF\u539F\u751F ComfyUI \u771F\u5B9E\u51FA\u56FE\uFF088188 \u4E0D\u53EF\u8FBE\u65F6\u8DF3\u8FC7\uFF09");
{
  const BASE = "http://127.0.0.1:8188";
  let engineUp = false;
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 3e3);
    const resp = await fetch(`${BASE}/system_stats`, { signal: ctrl.signal });
    clearTimeout(timer);
    engineUp = resp.ok;
  } catch {
    engineUp = false;
  }
  if (!engineUp) {
    console.log("  SKIP real-engine test (8188 not reachable)");
  } else {
    const cfg = getBuiltinWorkflowConfig("image", "Local SD1.5");
    expect(
      cfg && cfg.result?.node === "9" && Object.keys(cfg.api_json).length === 7,
      "builtin T2I template resolved (7 native nodes)"
    );
    expect(
      cfg && !Object.values(cfg.api_json).some((n2) => String(n2.class_type).startsWith("ComfyTV.")),
      "builtin template has no ComfyTV.* class_type (pure native ComfyUI)"
    );
    let promptId = null;
    let submitError = "";
    try {
      const resp = await fetch(`${BASE}/prompt`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: cfg.api_json, client_id: "e2e-real-engine" })
      });
      if (resp.ok) {
        const j = await resp.json();
        promptId = j.prompt_id ?? null;
      } else {
        submitError = "HTTP " + resp.status + " " + (await resp.text()).slice(0, 300);
      }
    } catch (e2) {
      submitError = String(e2 && e2.message || e2);
    }
    expect(promptId != null, "real-engine /prompt accepted (prompt_id=" + promptId + (submitError ? ", err=" + submitError : "") + ")");
    let completed = false;
    let images = [];
    const deadline = Date.now() + 18e4;
    while (promptId && Date.now() < deadline && !completed) {
      await new Promise((r) => setTimeout(r, 3e3));
      try {
        const h = await (await fetch(`${BASE}/history/${promptId}`)).json();
        if (h[promptId]) {
          const st = h[promptId].status?.status_str;
          if (st === "success") {
            completed = true;
            images = h[promptId].outputs?.["9"]?.images ?? [];
          } else if (st === "error") {
            break;
          }
        }
      } catch {
      }
    }
    expect(completed, "real-engine generation completed");
    expect(images.length >= 1, "real-engine produced \u22651 image");
    if (images[0]) {
      const img = images[0];
      const url = `${BASE}/view?filename=${img.filename}&subfolder=${img.subfolder || ""}&type=${img.type || "output"}`;
      let bytes = 0;
      try {
        bytes = (await (await fetch(url)).arrayBuffer()).byteLength;
      } catch {
        bytes = 0;
      }
      expect(bytes > 0, "real-engine image downloadable (" + bytes + " bytes, " + url + ")");
    }
  }
}
section("E2E: actions \u5B8C\u6574\u6027 \u2014 \u6BCF\u4E2A action \u90FD\u80FD spawn \u8282\u70B9 + \u8FDE\u7EBF\u7AEF\u53E3\u6709\u6548");
{
  registerDefaultComfyTVStages();
  const store = useWorkflowEditorStore.getState();
  const SRC_BY_KIND = {
    text: "ComfyTV.TextStage",
    image: "ComfyTV.ImageStage",
    "image-picker": "ComfyTV.ImagePickerStage",
    "image-batch": "ComfyTV.ImageStage",
    video: "ComfyTV.VideoStage",
    panorama: "ComfyTV.PanoramaStage",
    model: "ComfyTV.Model3DStage"
  };
  const flattened = [];
  for (const [kind, actions] of Object.entries(ACTIONS_BY_KIND)) {
    for (const a of actions) {
      if (a.presets?.length) {
        for (const p of a.presets) {
          flattened.push([kind, `${a.id}:${p.id}`, p.targetClass ?? null]);
        }
      } else {
        flattened.push([kind, a.id, null]);
      }
    }
  }
  let spawned = 0;
  let wired = 0;
  let skippedWire = 0;
  let spawnable = 0;
  for (const [kind, actionId, targetClass] of flattened) {
    const srcType = SRC_BY_KIND[kind];
    if (!srcType) {
      continue;
    }
    spawnable++;
    store.setNodes([{ id: "src", type: srcType, position: { x: 0, y: 0 }, data: {} }]);
    store.setEdges([]);
    spawnFollowUp("src", actionId);
    const s = useWorkflowEditorStore.getState();
    const created = s.nodes.filter((n2) => n2.id !== "src");
    const actionLabel = `${kind}:${actionId}`;
    expect(created.length >= 1, `${actionLabel} spawns \u22651 node`);
    for (const e2 of s.edges) {
      const srcSpec = getNodeSpec(s.nodes.find((n2) => n2.id === e2.source)?.type ?? "");
      const tgtSpec = getNodeSpec(s.nodes.find((n2) => n2.id === e2.target)?.type ?? "");
      const srcOk = srcSpec?.outputs?.some((o) => o.name === e2.sourceHandle);
      const tgtOk = tgtSpec?.inputs?.some((i) => i.name === e2.targetHandle);
      expect(srcOk, `${actionLabel} edge source port "${e2.sourceHandle}" exists on ${srcSpec?.type}`);
      expect(tgtOk, `${actionLabel} edge target port "${e2.targetHandle}" exists on ${tgtSpec?.type}`);
    }
    if (created.length >= 1) {
      spawned++;
    }
    if (s.edges.length > 0) {
      wired++;
    } else {
      skippedWire++;
    }
    if (targetClass) {
      expect(created.some((n2) => n2.type === targetClass), `${actionLabel} creates ${targetClass}`);
    }
  }
  expect(spawned === spawnable, `all ${spawnable} spawnable actions spawn nodes (got ${spawned})`);
  expect(wired > 0, "at least some actions produce wired edges");
  store.setNodes([]);
  store.setEdges([]);
}
section("E2E: action \u76EE\u6807\u8282\u70B9 spec \u5B8C\u6574\uFF08\u53EF\u6E32\u67D3\uFF09\u2014 title/kind/\u7AEF\u53E3");
{
  registerDefaultComfyTVStages();
  const targets = [
    // image edit presets
    "ComfyTV.UpscaleStage",
    "ComfyTV.OutpaintStage",
    "ComfyTV.InpaintStage",
    "ComfyTV.EraseStage",
    "ComfyTV.CutoutStage",
    "ComfyTV.CropStage",
    "ComfyTV.RotateStage",
    "ComfyTV.MirrorStage",
    "ComfyTV.ColorGradeStage",
    "ComfyTV.GridSplitStage",
    "ComfyTV.KenBurnsStage",
    // image variant presets
    "ComfyTV.ImageVariationsStage",
    "ComfyTV.ImageEditStage",
    // panorama / multiangle / relight / material / storyboard
    "ComfyTV.PanoramaStage",
    "ComfyTV.MultiangleStage",
    "ComfyTV.RelightStage",
    "ComfyTV.MaterialStage",
    "ComfyTV.StoryboardEditorStage",
    // video extend + change
    "ComfyTV.VideoExtractFrameStage",
    "ComfyTV.VideoStage",
    "ComfyTV.VideoClipStage",
    "ComfyTV.VideoSplitStage",
    "ComfyTV.VideoSpeedStage",
    "ComfyTV.VideoRotateStage",
    "ComfyTV.VideoCropStage",
    "ComfyTV.VideoResizeStage",
    "ComfyTV.VideoVolumeStage",
    "ComfyTV.VideoMuxAudioStage",
    "ComfyTV.VideoConcatStage",
    "ComfyTV.VideoFramesStage",
    "ComfyTV.VideoColorStage",
    "ComfyTV.VideoCurvesStage",
    "ComfyTV.VideoLUTStage",
    "ComfyTV.VideoBlurSharpenStage",
    "ComfyTV.VideoDenoiseStage",
    "ComfyTV.VideoChromaKeyStage",
    "ComfyTV.VideoTransitionStage",
    "ComfyTV.VideoStabilizeStage",
    "ComfyTV.VideoInterpolateStage",
    "ComfyTV.VideoStylizeStage",
    "ComfyTV.VideoScopesStage",
    "ComfyTV.VideoTransformStage",
    "ComfyTV.VideoCompositeStage",
    // model / text
    "ComfyTV.Model3DStage",
    "ComfyTV.TextStage"
  ];
  let resolved = 0;
  for (const t of targets) {
    const spec = getNodeSpec(t);
    expect(!!spec, `spec registered: ${t}`);
    if (!spec) {
      continue;
    }
    expect(typeof spec.title === "string" && spec.title.trim().length >= 2, `title usable: ${t} (got "${spec.title}")`);
    expect(!!spec.kind, `kind present: ${t}`);
    if (spec.kind === "schema") {
      expect((spec.inputs ?? []).length >= 1, `schema ${t} has \u22651 input port`);
      expect((spec.outputs ?? []).length >= 1, `schema ${t} has \u22651 output port`);
    }
    resolved++;
  }
  expect(resolved === targets.length, `all ${targets.length} action targets resolved (got ${resolved})`);
}
console.log("\n-- Summary --");
if (failures.length) {
  console.log("FAIL " + failures.length + " assertion(s) failed:");
  for (const f of failures) console.log("  - " + f);
  process.exit(1);
} else {
  console.log("PASS all e2e assertions green");
  process.exit(0);
}
